cd /workspace && python3 -c "
import random

def insertion_sort(arr):
    a = list(arr)
    n = len(a)
    for i in range(1, n):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def generate_partially_sorted(size, disorder_pct, seed):
    rng = random.Random(seed)
    data = list(range(size))
    k = int(size * disorder_pct / 100.0)
    if k > 0:
        indices = list(range(size))
        rng.shuffle(indices)
        for i in range(k):
            idx_a = indices[i]
            idx_b = indices[rng.randint(0, size - 1)]
            data[idx_a], data[idx_b] = data[idx_b], data[idx_a]
    return data

# Test all conditions that would be used
for size in [32, 128, 512]:
    for itype in ['sorted', 'disorder_10', 'random']:
        if itype == 'sorted':
            rng = random.Random(1)
            data = sorted([rng.randint(-1000, 1000) for _ in range(size)])
        elif itype == 'disorder_10':
            data = generate_partially_sorted(size, 10, 42)
        elif itype == 'random':
            rng = random.Random(42)
            data = [rng.randint(-1000, 1000) for _ in range(size)]

        expected = sorted(data)
        result = insertion_sort(data)
        ok = result == expected
        print(f'size={size:3d} {itype:15s} match={ok}')
        if not ok:
            for i in range(min(len(result), len(expected))):
                if result[i] != expected[i]:
                    print(f'  First mismatch at index {i}: got {result[i]}, expected {expected[i]}')
                    break
"

